/**
 * Remove icon assets generated by `tauri icon` that NoteZ (Windows-only) does not use.
 */
import { copyFileSync, existsSync, readdirSync, rmSync, unlinkSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const iconsDir = join(root, 'src-tauri/icons');

for (const dir of ['ios', 'android']) {
  const path = join(iconsDir, dir);
  if (existsSync(path)) {
    rmSync(path, { recursive: true, force: true });
    console.log('Removed', path);
  }
}

for (const name of readdirSync(iconsDir)) {
  if (/^Square\d+x\d+Logo\.png$/.test(name) || name === 'StoreLogo.png') {
    unlinkSync(join(iconsDir, name));
    console.log('Removed', name);
  }
}

for (const name of ['icon.icns', '64x64.png', 'icon.png']) {
  const path = join(iconsDir, name);
  if (existsSync(path)) {
    unlinkSync(path);
    console.log('Removed', name);
  }
}

const svgSrc = join(iconsDir, 'icon.svg');
const svgDst = join(root, 'public/notez-icon.svg');
if (existsSync(svgSrc) && existsSync(dirname(svgDst))) {
  copyFileSync(svgSrc, svgDst);
  console.log('Synced public/notez-icon.svg');
} else if (existsSync(svgSrc)) {
  console.warn('Skipped syncing public/notez-icon.svg: public/ directory does not exist.');
}
